/* ===================================================
   Prequalification Form Styles
   =================================================== */

.prequal-form-container {
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(10px);
  border-radius: 30px;
  padding: 60px;
  box-shadow: 0 30px 60px -12px rgba(16, 60, 59, 0.15), 0 18px 36px -18px rgba(0, 0, 0, 0.1);
  margin-top: -100px;
  position: relative;
  z-index: 10;
  border: 1px solid rgba(16, 60, 59, 0.05);
  border-top: 8px solid #2D9A96;
}

@media (max-width: 991px) {
  .prequal-form-container {
    padding: 30px;
    margin-top: 20px;
  }
}

.prequal-progress-wrapper {
  margin-bottom: 45px;
}

.step-count-text {
  font-size: 13px;
  font-weight: 800;
  color: #2D9A96;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  background: rgba(45, 154, 150, 0.1);
  padding: 6px 14px;
  border-radius: 30px;
}

.step-completion-percent {
  font-size: 13px;
  font-weight: 700;
  color: #103C3B;
  display: flex;
  align-items: center;
  gap: 8px;
}

.step-completion-percent::before {
  content: '';
  width: 8px;
  height: 8px;
  background: #2D9A96;
  border-radius: 50%;
  box-shadow: 0 0 10px rgba(45, 154, 150, 0.5);
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0% {
    transform: scale(1);
    opacity: 1;
  }

  50% {
    transform: scale(1.5);
    opacity: 0.5;
  }

  100% {
    transform: scale(1);
    opacity: 1;
  }
}

.prequal-progress-steps {
  display: flex;
  justify-content: space-between;
  position: relative;
  margin-bottom: 30px;
}

.prequal-progress-steps::before {
  content: '';
  position: absolute;
  top: 18px;
  left: 0;
  width: 100%;
  height: 4px;
  background: #f1f5f9;
  border-radius: 4px;
  z-index: 1;
}

.prequal-progress-bar {
  position: absolute;
  top: 18px;
  left: 0;
  height: 4px;
  background: linear-gradient(90deg, #103C3B, #2D9A96);
  border-radius: 4px;
  z-index: 2;
  transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1);
  width: 0%;
  box-shadow: 0 2px 10px rgba(45, 154, 150, 0.3);
}

.step-indicator {
  position: relative;
  z-index: 3;
  text-align: center;
  flex: 1;
}

.step-number {
  width: 40px;
  height: 40px;
  background: #fff;
  border: 2px solid #e2e8f0;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 12px;
  font-weight: 800;
  font-size: 16px;
  color: #94a3b8;
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
}

.step-indicator.active .step-number {
  border-color: #2D9A96;
  color: #fff;
  background: linear-gradient(135deg, #103C3B, #2D9A96);
  transform: translateY(-5px);
  box-shadow: 0 10px 15px -3px rgba(45, 154, 150, 0.4);
}

.step-indicator.completed .step-number {
  background: #f0fdfa;
  border-color: #2D9A96;
  color: #2D9A96;
}

.step-indicator.completed .step-number::after {
  content: '\f00c';
  font-family: 'Font Awesome 6 Free';
  font-weight: 900;
  font-size: 12px;
}

.step-indicator.completed .step-number span {
  display: none;
}

.step-label {
  font-size: 14px;
  font-weight: 700;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-top: 5px;
}

.step-indicator.active .step-label {
  color: #103C3B;
}

.prequal-step-title {
  font-size: 20px;
  font-weight: 800;
  color: #103C3B;
  margin-bottom: 35px;
  display: flex;
  align-items: center;
  gap: 15px;
  padding-bottom: 15px;
  border-bottom: 2px solid #f1f5f9;
}

.prequal-step-title i {
  color: #fff;
  background: linear-gradient(135deg, #2D9A96, #103C3B);
  width: 45px;
  height: 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  font-size: 20px;
  box-shadow: 0 8px 16px rgba(45, 154, 150, 0.2);
}

.prequal-step {
  display: none;
}

.prequal-step.active {
  display: block;
  animation: slideUp 0.6s cubic-bezier(0.4, 0, 0.2, 1) forwards;
  background: linear-gradient(180deg, rgba(240, 253, 250, 0.5) 0%, rgba(255, 255, 255, 0) 100%);
  padding: 15px;
  border-radius: 20px;
  margin: -30px;
  margin-bottom: 0;
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.form-group-label {
  display: block;
  font-size: 14px;
  font-weight: 700;
  color: #103C3B;
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.form-group-label span {
  color: #ef4444;
  margin-left: 2px;
}

.prequal-input,
.prequal-select,
.prequal-textarea {
  width: 100%;
  height: 60px;
  padding: 0 25px;
  border: 1.5px solid #e2e8f0;
  border-radius: 15px;
  background: #f8fafc;
  color: #1e293b;
  font-size: 16px;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.02);
}

.prequal-input::placeholder,
.prequal-textarea::placeholder {
  color: #7c858c !important;
  font-size: 16px !important;
  opacity: 1;
}

.prequal-select {
  background-image: url("data:image/svg+xml;charset=UTF-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2212%22%20height%3D%2212%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%2364748b%22%20stroke-width%3D%223%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpolyline%20points%3D%226%209%2012%2015%2018%209%22%3E%3C%2Fpolyline%3E%3C%2Fsvg%3E") !important;
  background-repeat: no-repeat !important;
  background-position: right 25px center !important;
  cursor: pointer !important;
  padding-right: 50px !important;
}

.prequal-select:hover {
  border-color: #2D9A96 !important;
  background-color: #ffffff !important;
}

.prequal-input.invalid,
.prequal-select.invalid,
.prequal-textarea.invalid {
  border-color: #ef4444 !important;
  background-color: #fef2f2 !important;
  box-shadow: 0 0 0 4px rgba(239, 68, 68, 0.1) !important;
}

.prequal-textarea {
  height: 120px;
  padding: 15px 20px;
  resize: none;
}

.prequal-input:focus,
.prequal-select:focus,
.prequal-textarea:focus {
  outline: none;
  background: #fff;
  border-color: #2D9A96;
  box-shadow: 0 0 0 4px rgba(45, 154, 150, 0.15), 0 4px 12px rgba(45, 154, 150, 0.1);
  transform: translateY(-1px);
}

/* Support for nice-select which is active in this project */
.prequal-form .nice-select {
  width: 100%;
  height: 60px;
  line-height: 58px;
  padding: 0 25px;
  border: 1.5px solid #e2e8f0;
  border-radius: 15px;
  background: #f8fafc;
  color: #1e293b;
  font-size: 16px;
  float: none;
  transition: all 0.3s ease;
}

.prequal-form .nice-select .current {
  color: #7c858c !important;
  font-size: 16px;
}

.prequal-form .nice-select:hover {
  border-color: #2D9A96;
  background: #fff;
}

.prequal-form .nice-select:after {
  border-bottom: 2px solid #64748b;
  border-right: 2px solid #64748b;
  height: 8px;
  width: 8px;
  right: 20px;
  transform: rotate(45deg);
  margin-top: -6px;
}

.prequal-form .nice-select.open:after {
  transform: rotate(-135deg);
}

.select-wrapper {
  position: relative;
  z-index: 1;
}

/* Ensure open dropdowns are always on top */
.select-wrapper:focus-within,
.select-wrapper:hover {
  z-index: 50;
}

.prequal-form .nice-select.open {
  z-index: 999 !important;
}

.prequal-form .nice-select .list {
  width: 100%;
