  transition: color 0.2s ease;
}

.sba-faq-item.active .sba-faq-q span,
.sba-faq-q:hover span {
  color: #2D9A96;
}

.sba-faq-q i {
  font-size: 14px;
  color: #aaa;
  transition: transform 0.3s ease, color 0.3s ease;
  flex-shrink: 0;
}

.sba-faq-item.active .sba-faq-q i {
  transform: rotate(180deg);
  color: #2D9A96;
}

.sba-faq-a {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
}

.sba-faq-item.active .sba-faq-a {
  max-height: 200px;
  padding-bottom: 20px;
}

.sba-faq-a p {
  font-size: 15px;
  line-height: 1.7;
  color: #666;
  margin: 0;
}

/* --- Article CTA Block --- */
.sba-cta-block {
  background: linear-gradient(135deg, #103C3B 0%, #1a5857 100%);
  border-radius: 24px;
  padding: 45px;
  text-align: center;
  margin-bottom: 40px;
  position: relative;
  overflow: hidden;
}

.sba-cta-block::before {
  content: '';
  position: absolute;
  top: -50px;
  right: -50px;
  width: 200px;
  height: 200px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.04);
}

.sba-cta-icon {
  width: 64px;
  height: 64px;
  background: rgba(255, 255, 255, 0.12);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
  color: #4BD7D4;
  margin: 0 auto 20px;
}

.sba-cta-block h3 {
  color: #fff;
  font-size: 26px;
  font-weight: 700;
  margin-bottom: 16px;
}

.sba-cta-block h3 em {
  color: #4BD7D4;
  font-style: normal;
}

.sba-cta-block p {
  color: rgba(255, 255, 255, 0.75);
  font-size: 16px;
  line-height: 1.7;
  margin-bottom: 28px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

.sba-cta-block .theme-btn {
  display: inline-flex;
}

/* --- Sticky Sidebar --- */
.sba-sticky-sidebar {
  position: sticky;
  top: 100px;
}

.sba-sidebar-nav {
  background: #fff;
  border-radius: 16px;
  padding: 28px;
  border: 1px solid #eee;
  margin-bottom: 24px;
}

.sba-nav-list {
  margin: 0;
}

.sba-nav-list li {
  margin-bottom: 4px;
}

.sba-nav-list li a {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 15px;
  color: #444;
  font-weight: 500;
  transition: all 0.25s ease;
  text-decoration: none;
}

.sba-nav-list li a:hover {
  background: rgba(45, 154, 150, 0.08);
  color: #2D9A96;
  padding-left: 20px;
}

.sba-nav-list li a i {
  color: #2D9A96;
  font-size: 14px;
  width: 18px;
}

/* Key Metrics Sidebar */
.sba-sidebar-metrics {
  background: #fff;
  border-radius: 16px;
  padding: 28px;
  border: 1px solid #eee;
  margin-bottom: 24px;
}

.sba-metric-mini {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.sba-metric-mini-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px dashed #e8e8e8;
}

.sba-metric-mini-row:last-child {
  border-bottom: none;
}

.sba-mini-label {
  font-size: 14px;
  color: #888;
}

.sba-mini-val {
  font-size: 15px;
  font-weight: 700;
  color: #103C3B;
}

/* Sidebar CTA */
.sba-sidebar-cta {
  background: linear-gradient(135deg, #103C3B, #2D9A96);
  border-radius: 16px;
  padding: 30px;
  margin-bottom: 24px;
  text-align: center;
}

.sba-sidebar-cta h3 {
  color: #fff;
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 12px;
}

.sba-sidebar-cta p {
  color: rgba(255, 255, 255, 0.75);
  font-size: 14px;
  line-height: 1.6;
  margin-bottom: 20px;
}

/* --- Utility --- */
.pt-100 {
  padding-top: 100px !important;
}

.mb-50 {
  margin-bottom: 50px;
}

.mt-40 {
  margin-top: 40px;
}

/* --- Responsive --- */
@media (max-width: 991px) {
  .sba-sticky-sidebar {
    position: static;
    margin-top: 50px;
  }

  .sba-case-math {
    gap: 10px;
  }

  .sba-case-operator {
    font-size: 22px;
  }

  .sba-intro-title {
    font-size: 22px;
  }
}

@media (max-width: 575px) {
  .sba-case-math {
    flex-direction: column;
    align-items: stretch;
  }

  .sba-case-operator {
    text-align: center;
  }

  .sba-credit-tiers {
    flex-direction: column;
  }

  .sba-cta-block {
    padding: 30px 20px;
  }
}

.sba-intro-title {
  font-size: 22px;
}

/* Form Response Alert Messages */
.form-alert {
  margin-bottom: 1rem;
  padding: 0.75rem 1rem;
  border-radius: 6px;
  font-size: 15px;
  line-height: 1.5;
}

.form-alert--success {
  background: #d4edda;
  color: #155724;
  border: 1px solid #c3e6cb;
}

.form-alert--error {
  background: #f8d7da;
  color: #721c24;
  border: 1px solid #f5c6cb;
}

/* =============================================
   Searchable Select Component
   ============================================= */
.ss-wrapper {
  position: relative;
  width: 100%;
  user-select: none;
}

.ss-hidden-select {
  position: absolute;
  opacity: 0;
  pointer-events: none;
  width: 1px;
  height: 1px;
}

.ss-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  height: 60px;
  padding: 0 20px;
  border: 1.5px solid #e2e8f0;
  border-radius: 15px;
  background: #f8fafc;
  color: #1e293b;
  font-size: 16px;
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.02);
}

.ss-trigger:hover,
.ss-trigger.ss-open {
  border-color: #2D9A96;
  background: #fff;
  box-shadow: 0 0 0 4px rgba(45, 154, 150, 0.12);
}

.ss-trigger.ss-placeholder .ss-trigger-label {
  color: #7c858c;
}

.ss-trigger-label {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 16px;
}

.ss-trigger-icons {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
  margin-left: 10px;
}

.ss-clear {
  font-size: 12px;
  color: #999;
  cursor: pointer;
  padding: 2px 5px;
  border-radius: 50%;
  line-height: 1;
  transition: color 0.2s ease, background 0.2s ease;
}

.ss-clear:hover {
  color: #dc3545;
  background: rgba(220, 53, 69, 0.08);
}

.ss-chevron {
  font-size: 14px;
  color: #64748b;
  transition: transform 0.3s ease;
  display: inline-block;
}

.ss-chevron.ss-chevron-up {
  transform: rotate(180deg);
}

.prequal-error .ss-trigger,
.prequal-input.prequal-error,
.prequal-textarea.prequal-error {
  border-color: #ef4444 !important;
  background: #fef2f2 !important;
  box-shadow: 0 0 0 4px rgba(239, 68, 68, 0.1) !important;
}

/* Dropdown panel */
.ss-dropdown {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  background: #fff;
  border: 1.5px solid #e2e8f0;
  border-radius: 14px;
  box-shadow: 0 12px 40px rgba(16, 60, 59, 0.12);
  z-index: 9999;
  overflow: hidden;
  animation: ssDropIn 0.18s ease;
}

@keyframes ssDropIn {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Search box */
.ss-search-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 15px;
  border-bottom: 0px solid #f1f5f9;
}

.ss-search-icon {
  font-size: 14px;
  flex-shrink: 0;
  opacity: 0.5;
}

.ss-search {
  flex: 1;
  border: none;
  outline: none;
  background: transparent;
  font-size: 15px;
  color: #1e293b;
}

.ss-search::placeholder {
  color: #94a3b8;
}

/* Options list */
.ss-list {
  list-style: none;
  margin: 0;
  padding: 6px 0;
  max-height: 220px;
  overflow-y: auto;
}

.ss-list::-webkit-scrollbar {
  width: 5px;
}

.ss-list::-webkit-scrollbar-track {
  background: transparent;
}

.ss-list::-webkit-scrollbar-thumb {
  background: #e2e8f0;
  border-radius: 50px;
}

.ss-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 15px;
  font-size: 15px;
  color: #334155;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.ss-option:hover {
  background: rgba(45, 154, 150, 0.07);
  color: #2D9A96;
}

.ss-option.ss-selected {
  background: rgba(16, 60, 59, 0.06);
  color: #103C3B;
  font-weight: 600;
}

.ss-check {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  background: rgba(45, 154, 150, 0.1);
  border-radius: 50%;
  color: #2D9A96;
  font-size: 11px;
  flex-shrink: 0;
}

.prequal-country-dropdown {
  position: relative;
  min-width: 140px;
  height: 60px;
  margin-right: 15px;
  z-index: 10;
}

.prequal-country-trigger {
  width: 100%;
  height: 100%;
  padding: 0 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #2D9A96;
  border-radius: 15px;
  color: white;
  font-weight: 600;
  font-size: 16px;
  cursor: pointer;
  transition: all 0.3s ease;
}

.prequal-country-trigger:hover {
  background: #237e7b;
}

.rotate-180 {
  transform: rotate(180deg);
}

.prequal-country-list {
  position: absolute;
  top: calc(100% + 10px);
  left: 0;
  width: 100%;
  background: white;
  border-radius: 15px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
  overflow: hidden;
  animation: ssDropIn 0.3s ease;
}

.prequal-country-item {
  padding: 12px 20px;
  font-size: 14px;
  color: #1a2b3c;
  cursor: pointer;
  transition: all 0.2s ease;
}

.prequal-country-item:hover,
.prequal-country-item.active {
  background: #f1f5f9;
  color: #2D9A96;
}

/* Ensure phone group handles the new layout */
.phone-input-group {
  display: flex;
  align-items: center;
}


/* Funding Card Link Styling */
.funding-card-link {
  position: absolute;
  bottom: 25px;
  right: 25px;
  width: 40px;
  height: 40px;
  background: #103C3B;
  color: #fff;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  transition: all 0.3s ease;
  z-index: 10;
