.tier-title {
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 20px;
  color: #111827;
  line-height: 1.3;
}

.tier-points {
  list-style: none;
  padding: 0;
  margin: 0 0 25px 0;
  flex-grow: 1;
}

.tier-points li {
  position: relative;
  padding-left: 28px;
  margin-bottom: 12px;
  font-size: 15px;
  color: #4b5563;
  line-height: 1.5;
}

.tier-points li::before {
  content: "\f058";
  font-family: "Font Awesome 6 Free";
  font-weight: 900;
  position: absolute;
  left: 0;
  top: 3px;
  color: #2D9A96;
}

.tier-footer {
  font-size: 14px;
  color: #6b7280;
  padding-top: 20px;
  border-top: 1px solid #f3f4f6;
  font-style: italic;
}

.mistake-card {
  background: #fff4f4;
  border-radius: 16px;
  padding: 20px;
  border-left: 4px solid #ef4444;
}

.mistake-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.mistake-list li {
  display: flex;
  align-items: center;
  gap: 12px;
  color: #991b1b;
  font-weight: 500;
  margin-bottom: 10px;
}

.pricing-footer {
  margin-top: 30px;
  font-size: 15px;
  color: #6b7280;
  text-align: center;
}

.who-for-section {
  background: #f9fafb;
}

.designed-for-box {
  background: #fff;
  border-radius: 20px;
  padding: 30px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
  height: 100%;
}

.not-designed-box {
  background: #fef2f2;
  border-radius: 20px;
  padding: 30px;
  height: 100%;
}

.growth-footer-disclaimer {
  margin-top: 30px;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.6);
  max-width: 800px;
  margin-left: auto;
  margin-right: auto;
}

.custom-address {
  line-height: 26px;
  max-width: 350px;
}

/* Custom Sidebar Search */
.custom-sidebar-search-wrapper {
  padding: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  margin-bottom: 30px;
}

.custom-sidebar-search {
  background-color: #103C3B;
  border-radius: 12px;
  display: flex;
  align-items: center;
  padding: 0 25px;
  height: 60px;
  width: 100%;
}

.custom-sidebar-search input {
  flex: 1;
  background: transparent !important;
  border: none !important;
  color: #fff !important;
  font-size: 16px;
  outline: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  width: 100%;
}

.custom-sidebar-search input::placeholder {
  color: rgba(255, 255, 255, 0.7) !important;
}

.custom-sidebar-search button {
  background: transparent !important;
  border: none !important;
  color: #fff !important;
  font-size: 20px;
  cursor: default;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Modern Pagination */
.modern-pagination {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
  list-style: none;
  padding: 0;
  margin: 40px 0 0 0;
}

.modern-pagination li {
  display: inline-flex;
}

.modern-pagination li a {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 45px;
  height: 45px;
  border-radius: 8px;
  background-color: #f4f5f6;
  color: #103C3B;
  font-weight: 600;
  font-size: 16px;
  text-decoration: none;
  transition: all 0.3s ease;
  border: 1px solid transparent;
}

.modern-pagination li a:hover {
  background-color: #e5e7eb;
  color: #103C3B;
}

.modern-pagination li a.active {
  background-color: #103C3B;
  color: #ffffff;
  border-color: #103C3B;
  box-shadow: 0 4px 10px rgba(16, 60, 59, 0.2);
}

.modern-pagination li a i {
  font-size: 14px;
}

